function analyze_left150_crossdistance
out=fileparts(mfilename('fullpath'));base=fileparts(out);diary(fullfile(out,'holdout_matlab_diary.log'));P=jsondecode(fileread(fullfile(base,'four-direction-short-analysis','parameters.json')));prior=jsondecode(fileread(fullfile(out,'frozen_left210_coordinate_candidate.json')));d=jsondecode(fileread(fullfile(out,'capture','decoded.json')));h=d.header;tr=double(h.trigger_ms);assert(h.quality==0 && h.frozen && ~h.truncated && h.terminal_tail_completed);assert(h.wheel_dropped==0 && h.hwt_dropped==0 && h.od_dropped==0);assert(all(diff([d.raw.sample_sequence])==1));ts=cell(1,4);xs=ts;lo=0;hi=(double(d.raw(end).service_ms)-tr)/1000;
for j=1:4
 a=d.wheel(strcmp({d.wheel.source},'position') & [d.wheel.valid] & [d.wheel.wheel]==j-1);t=(double([a.source_ms]')-tr)/1000;x=double([a.value]').*(1-2*double([a.sign]'))*P.motor_forward_sign(j)*pi*P.wheel_diameter_mm/P.counts_per_rev;[t,ix]=unique(t,'last');ts{j}=t;xs{j}=x(ix);lo=max(lo,t(1));hi=min(hi,t(end));
end
a=d.hwt([d.hwt.healthy] & bitand([d.hwt.valid_mask],1)~=0);ht=(double([a.angle_ms]')-tr)/1000;hy=unwrap(double([a.yaw_deg]')*pi/180);[ht,ix]=unique(ht,'last');hy=hy(ix);lo=max(lo,ht(1));hi=min(hi,ht(end));assert(lo<=0);q=(0:.005:floor((hi+1e-10)/.005)*.005)';pos=zeros(numel(q),4);for j=1:4,pos(:,j)=interp1(ts{j},xs{j},q);end
yaw=interp1(ht,hy,q);ref=(h.path_heading_deg-h.heading_offset_deg)*pi/180;dw=diff(pos);F=mean(dw,2)*P.forward_scale;L=(dw(:,1)-dw(:,2)-dw(:,3)+dw(:,4))/4;half=diff(yaw)/2;mid=(yaw(2:end)+yaw(1:end-1))/2-ref;si=ones(size(half));nz=abs(half)>1e-10;si(nz)=sin(half(nz))./half(nz);fp=[0 0;cumsum([si.*F.*cos(mid),si.*F.*sin(mid)],1)];lp=[0 0;cumsum([-si.*L.*sin(mid),si.*L.*cos(mid)],1)];path=fp+lp;body=[0 0;cumsum([F L],1)];
od=d.od;od=od([od.valid] & [od.reasons]==0 & [od.continuity_lost]==0);ot=(double([od.sample_ms]')-tr)/1000;[ot,ix]=unique(ot,'last');od=od(ix);theta=h.path_heading_deg*pi/180;dx=double([od.x_mm]')-h.origin_x_mm;dy=double([od.y_mm]')-h.origin_y_mm;fl=[dx*cos(theta)+dy*sin(theta),-dx*sin(theta)+dy*cos(theta)];z=find(q>=ot(1) & q<=ot(end),1,'last');v=interp1(ot,fl,q(z));
S=struct('status','PASS_DIAGNOSTIC_WITH_LIMITATIONS','matlab_version',version,'ground_measurement_read',false,'diagnostic_not_deployable',true,'hardware_access',false,'target_left_mm',1500,'common_end_s',q(end),'STOP_s',(double(h.stop_ms)-tr)/1000,'terminal_receiver_s',(double(h.first_terminal_receiver_ms)-tr)/1000,'terminal_minus_common_end_s',(double(h.first_terminal_receiver_ms)-tr)/1000-q(end),'main_left_mm',path(end,2),'cross_forward_mm',path(end,1),'body_F_mm',body(end,1),'body_L_mm',body(end,2),'F_project_F_mm',fp(end,1),'F_project_L_mm',fp(end,2),'L_project_F_mm',lp(end,1),'L_project_L_mm',lp(end,2),'yaw_effect_main_mm',path(end,2)-body(end,2),'yaw_effect_cross_mm',path(end,1)-body(end,1),'OD_match_s',q(z),'OD_main_error_mm',path(z,2)-v(2),'OD_cross_error_mm',path(z,1)-v(1),'frozen_gamma',prior.main_scale_gamma,'frozen_beta',prior.cross_model_minus_ground_per_main_beta,'corrected_left_prediction_mm',prior.main_scale_gamma*path(end,2),'corrected_forward_prediction_mm',path(end,1)-prior.cross_model_minus_ground_per_main_beta*path(end,2),'training_version','79e74f1f','new_version','79e74f1f','version_equal',true,'cross_distance_holdout',true,'ground_read_for_fit',false,'source_time_not_physical_time',true,'ground_truth_synchronized',false);
assert(abs(S.OD_main_error_mm)<.01);fid=fopen(fullfile(out,'holdout_prediction.json'),'w','n','UTF-8');fwrite(fid,jsonencode(S),'char');fclose(fid);T=table(q,path(:,1),path(:,2),body(:,1),body(:,2),fp(:,1),fp(:,2),lp(:,1),lp(:,2),(yaw-ref)*180/pi,'VariableNames',{'source_s','path_F_mm','path_L_mm','body_F_mm','body_L_mm','F_project_F_mm','F_project_L_mm','L_project_F_mm','L_project_L_mm','yaw_deg'});writetable(T,fullfile(out,'holdout_decomposition.csv'));disp(S);diary off;
end
